select
from aqi_feedback af left join grid_member gm on af.gm_id = gm.gm_id inner join supervisor su on af.tel_id = su.tel_id inner join grid_province gp on af.province_id = gp.province_id inner join grid_city gc on af.city_id = gc.city_id left join aqi aq on af.estimated_grade = aq.aqi_id
AND af.gm_id = #{gmId}
AND af.state = #{state}
order by af.af_date desc,af.af_time desc

SELECT COUNT(1)
FROM aqi_feedback af

    AND af.province_id = #{provinceId}
    AND af.city_id = #{cityId}
    AND af.estimated_grade = #{estimatedGrade}
    AND af.af_date LIKE CONCAT('%', #{afDate}, '%')
    AND af.state = #{state}

select

from aqi_feedback af
left join grid_member gm on af.gm_id = gm.gm_id
inner join supervisor su on af.tel_id = su.tel_id
inner join grid_province gp on af.province_id = gp.province_id
inner join grid_city gc on af.city_id = gc.city_id
left join aqi aq on af.estimated_grade = aq.aqi_id

    AND af.province_id = #{provinceId}
    AND af.city_id = #{cityId}
    AND af.estimated_grade = #{estimatedGrade}
    AND af.af_date LIKE CONCAT('%', #{afDate}, '%')
    AND af.state = #{state}

ORDER BY af.af_date DESC, af.af_time DESC
LIMIT #{beginNum}, #{maxPageNum}
